MODS[43] = "【佛答·扶策·象陷泥·复王位三喻】莫作是说。譬如有人迷闷倒地，依人扶策即得身起；也如大象陷在泥中，人不能起那象身，须得别的象扶翼而出；又如有人受灌顶王位，或于后时失去王位，凡常之人无能护卫，唯有有力的大臣、威势强勇者能恢复王位。【义解】佛以三喻回答：迷倒者依人扶起、陷象须别象扶出、失位之王须力臣恢复。喻佛弟子无论持戒与否，皆可依三宝与善知识之力而得利益、复其善根；故供养三宝、护持僧众皆成福利。"
MODS[44] = "【依法不依法俱成利益·大众庆喜】师子意菩萨！我教法中也是如此。若有依法者、不依法者，都是佛子，皆成利益；若生轻毁之心，何处得福？」那时一切大众闻此语已，异口同音、高声唱言：「世尊！我们如今蒙佛度脱、大得欣庆，能令一切众生得意愿圆满。【义解】此段佛总结：教法中依法与不依法者皆是佛子、皆成利益；若生轻毁则无福可得。大众闻已，异口同音庆喜，赞叹蒙佛度脱、令众生满愿。下文佛赞受持书写此陀罗尼之福德。"
MODS[45] = "【受持书写此陀罗尼之福德】」佛言：「若有人于此陀罗尼正法，或自己书写、或使人书写，受持读诵、恭敬供养，所获福德殊胜最上。若又有人这样见闻观自在菩萨摩诃萨所传第二法轮大力陀罗尼正法之名，此人便是建法幢、吹法螺，深种善根。【义解】此段佛说受持、书写、读诵、供养此陀罗尼的殊胜福德；并说能见闻观音所传「第二法轮大力陀罗尼」之名者，即是建立法幢、吹大法螺、深种善根。"
MODS[46] = "【梵寿王发愿·造寺·不侵常住】」那时梵寿王及一切大众发净信心，即从座起，合掌向佛而发誓言：「愿我等今后永不侵受佛寺、塔庙、圣众的常住之物，及一花一菓。又在四大城门造四大寺，皆以七宝庄严。愿佛证知。」佛言：「如是如是。宜作胜（殊胜之）利，远离嫉妒，得正寂灭。【义解】此段说梵寿王与大众发愿：今后永不侵损佛寺塔庙、圣众的常住之物乃至一花一果，并于四大城门造四大寺、以七宝庄严，请佛证知。佛印可并勉以远离嫉妒、得正寂灭。"
MODS[47] = "【王还归说法·王妹化宫女转男身】」那时梵寿王作此愿已，绕佛三匝，与其眷属还归本处，又为百千众生宣说此正法，广行布施、造大佛寺。那时王妹酥钵哩野优婆夷（女居士），于王后宫为诸婇女五十万人广说妙法、发诚实愿。作此愿已，这些宫女皆转女身而成男子。【义解】此段说王还归后为百千众生说法、广行布施造寺；王妹酥钵哩野以优婆夷身，为后宫五十万婇女说法发愿，众宫女皆转女身成男。此为「不受女身」之愿的现证，正回应前文王妹厌女身之问。"
MODS[48] = "【众惊信受·归依三宝·大众奉行】那些人见此事已皆大惊怪，于陀罗尼法信受依行，高声唱言：「唯有佛、唯有法、唯有僧，是最上福田，是真正的归依之处。若有供养、受持此陀罗尼者，此人种佛善根、得福最上。」佛说此经已，诸菩萨摩诃萨及天、人、阿修罗、乾闼婆、人非人等，皆大欢喜、信受而去。【义解】此段收结：众人见宫女转男之瑞皆大惊怪，于陀罗尼法信受依行，高声赞叹三宝为最上福田、真归依处，并赞供养受持此陀罗尼者种佛善根、得福最上。末说佛说经已，菩萨、天人、八部众皆大欢喜、信受而去，全经圆满。"

assert len(MODS)==len(task['translations']) and None not in MODS, f"MODS {len(MODS)}"
trans=[]
for i,mod in enumerate(MODS):
    mm=re.match(r'(【[^】]+】)',mod); sec=mm.group(1) if mm else f"【段{i+1}】"
    trans.append({"section":sec,"original_preview":task['translations'][i]['original_preview'],"modern":mod})
out={"id":TID,"title":TITLE,"translator":TRANSLATOR,"mode":"白話精譯","intro":INTRO,"sutraPath":task['sutraPath'],"translations":trans}
os.makedirs('data/modern-translation',exist_ok=True)
with open(f'data/modern-translation/{TID}.json','w',encoding='utf-8') as f:
    json.dump(out,f,ensure_ascii=False,indent=2)
print(f'Wrote {TID} {len(trans)}')
